import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachConfigurableFreeControl } from "@babylonjs/lite";

// Default rise/sink keys from attachFreeControl (camera-notes.md, note 55).
// upKeys/downKeys replace the defaults in the configurable control (note 16),
// so they are passed explicitly to keep the same keys.
const UP_KEYS = ["Space", "PageUp"] as const;
const DOWN_KEYS = ["ShiftLeft", "ShiftRight", "PageDown"] as const;

// WASD and arrow keys (camera-notes.md, note 55).
const MOVE_KEYS = [
    "KeyW", "KeyA", "KeyS", "KeyD",
    "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight",
] as const;

const FAST_MULTIPLIER = 20;

export function attachBigWorldFly(camera: FreeCamera, canvas: HTMLCanvasElement, scene: SceneContext): () => void {
    // Every movement key is listed as a "fast" key, so holding any of them
    // moves the camera at fastMultiplier times the default speed.
    // The returned disposer removes all listeners and the per-frame hook.
    return attachConfigurableFreeControl(camera, canvas, scene, {
        upKeys: UP_KEYS,
        downKeys: DOWN_KEYS,
        fastKeys: [...MOVE_KEYS, ...UP_KEYS, ...DOWN_KEYS],
        fastMultiplier: FAST_MULTIPLIER,
    });
}
```

I built this on `attachConfigurableFreeControl`, not `attachFreeControl`, because the configurable version can scale movement keys by a multiplier and `attachFreeControl` cannot. The result is a thin wrapper that adds no listeners of its own.

I'm not sure of several things:
- The notes don't say whether the configurable control's mouse look matches `attachFreeControl` exactly. Your requirement on mouse look should be checked by comparing a drag against the stock control.
- I don't know whether `attachConfigurableFreeControl` is exported from the package root `"@babylonjs/lite"`. It may need a subpath import.
- I don't know if the configurable control's default key sets match `attachFreeControl`'s. I passed the stock rise/sink keys explicitly so this shouldn't matter.
- I haven't confirmed that the multiplier scales the whole per-frame movement, including inertia decay, by exactly 20.
